-- 000001 foundation: extensions, shared enums, helper functions.
-- Conventions used across all migrations:
--   * Primary keys are UUIDs generated by the database (gen_random_uuid()).
--   * Money is stored as BIGINT minor units (KES cents) in columns ending _minor.
--   * Timestamps are TIMESTAMPTZ in UTC. Every mutable table has created_at/updated_at.
--   * Columns ending _enc hold application-encrypted bytes (AWS KMS envelope encryption
--     done in the Go service). The database never sees the plaintext of these fields.
--   * Soft state is modelled with explicit status enums rather than deleted rows, so the
--     audit trail and retention schedule stay intact.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Human-readable references shown to clients and staff (e.g. REQ-2026-000123).
CREATE SEQUENCE request_ref_seq;
CREATE SEQUENCE application_ref_seq;
CREATE SEQUENCE complaint_ref_seq;
CREATE SEQUENCE invoice_ref_seq;

CREATE TYPE user_kind AS ENUM ('client', 'provider', 'staff');
CREATE TYPE account_status AS ENUM ('pending_verification', 'active', 'suspended', 'closed');

-- Staff roles map to the segregation-of-duties rules in report §7.11.
CREATE TYPE staff_role AS ENUM (
  'admin',                -- user and configuration management
  'vetting_officer',      -- verifies documents, referees, interviews
  'approver',             -- management approval of applications (never the vetter)
  'training_coordinator',
  'triage_officer',       -- receives requests, selects providers
  'supervisor',           -- spot checks, complaint investigation
  'complaints_manager',   -- decides complaint outcomes
  'finance',              -- payments, payouts, reconciliation
  'compliance',           -- document expiry, re-verification, data protection
  'reporting'             -- read-only reports
);
